import type { Currency } from './currency-model';

export interface LaborCategory {
  /**
   * @displayName Labor Category
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Labor Category Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  laborCategoryName: string;
  /**
   * @displayName Currency
   */
  currency?: Pick<Currency, 'id' | 'currencyName'>;
  /**
   * @displayName Exchange Rate
   */
  exchangeRate?: number;
  /**
   * @displayName Labor Bill Rate
   * @validationRule Required for create/update operations
   */
  laborBillRate: number;
  /**
   * @displayName Labor Bill Rate (Base)
   */
  laborBillRateBase?: number;
  /**
   * @displayName Labor Cost Rate
   * @validationRule Required for create/update operations
   */
  laborCostRate: number;
  /**
   * @displayName Labor Cost Rate (Base)
   */
  laborCostRateBase?: number;
}

export const _LaborCategory = 'LaborCategory' as const;